from collections import deque

def bfs(start, grid, visited):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([start])
    visited[start] = True
    group = []

    while queue:
        x, y = queue.popleft()
        group.append((x, y))

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.' and not visited[(nx, ny)]:
                visited[(nx, ny)] = True
                queue.append((nx, ny))

    return group

